<script>
import generalMixin from "../../mixins/general";
import PerformanceCalendar from "./performance-calendar.vue";
export default {
  name: "PerformanceLanding",
  mixins: [generalMixin],
  props: ["queries"],
  components: { PerformanceCalendar },

  data() {
    return {
      selectedFiscalYear: "",
      activePeriod: "aprilsept",
      supervisees: [],
      loadingSupervisees: false,
      superviseesFetched: false,
      // Performance config window states — loaded from /fhir/Parameters/performance-config
      perfConfig: {},
      perfConfigLoaded: false,
      semesters: [
        { code: "aprilsept", label: "Semester 1", range: "Apr – Sep" },
        { code: "octmarch", label: "Semester 2", range: "Oct – Mar" },
      ],
    };
  },

  computed: {
    periodLabel() {
      return this.activePeriod === "aprilsept"
        ? "April \u2013 September"
        : "October \u2013 March";
    },
    activeSemesterLabel() {
      const sem = this.semesters.find((s) => s.code === this.activePeriod);
      return sem ? `${sem.label} (${sem.range})` : "";
    },
    basePath() {
      return this.queries.path || "";
    },
    goalSettingOpen() {
      return this.perfConfigLoaded
        ? this.perfConfig["goal-settings"]?.isOpen || false
        : true;
    },
    yearEndReviewOpen() {
      return this.perfConfigLoaded
        ? this.perfConfig["year-end-review"]?.isOpen || false
        : true;
    },
    // Returns window state for the given period code:
    //   Semester 1 (aprilsept) → mid-year-review window
    //   Semester 2 (octmarch)  → year-end-review window
    reviewWindowForPeriod() {
      return (periodCode) => {
        if (!this.perfConfigLoaded) return { isOpen: true };
        const key =
          periodCode === "aprilsept" ? "mid-year-review" : "year-end-review";
        return this.perfConfig[key] || { isOpen: false };
      };
    },
    goalAdjustmentWindow() {
      return this.reviewWindowForPeriod("aprilsept");
    },
    reviewLinks() {
      const reviewers = [
        {
          code: "self",
          label: "Self",
          icon: "mdi-account-edit",
          color: "#f97316",
          bg: "#fff7ed",
          borderColor: "rgba(249,115,22,0.25)",
        },
        {
          code: "supervisor",
          label: "Supervisor",
          icon: "mdi-clipboard-account",
          color: "#0d9488",
          bg: "#f0fdfa",
          borderColor: "rgba(13,148,136,0.25)",
        },
        {
          code: "joint",
          label: "Joint",
          icon: "mdi-handshake",
          color: "#6366f1",
          bg: "#eef2ff",
          borderColor: "rgba(99,102,241,0.25)",
        },
      ];
      const links = [];
      for (const rv of reviewers) {
        links.push({
          key: `${rv.code}`,
          reviewer: rv.code,
          label: `${rv.label}`,
          ...rv,
        });
      }
      return links;
    },
  },

  async mounted() {
    await this.$nextTick();
    // Wait for user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (v) => {
        if (!v) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    if (!this.queries.practitioner) {
      this.queries.practitioner = this.$store.state.user?.obj?.resource?.extension
        ?.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference"
          );
        })
        ?.valueReference?.reference?.split("/")?.[1];
    }

    // Load current fiscal year
    try {
      let fy = await fetch("/site/leave/getFinancialYear");
      fy = await fy.json();
      this.selectedFiscalYear = fy.year;
    } catch (e) {
      console.error(e);
    }

    // Determine current period based on current month
    const month = new Date().getMonth() + 1; // 1-12
    this.activePeriod = month >= 4 && month <= 9 ? "aprilsept" : "octmarch";

    // Load performance config windows
    await this.loadPerfConfig();

    // Load supervisees
    await this.loadSupervisees();
  },

  methods: {
    async loadSupervisees() {
      if (!this.queries.practitioner) return;
      this.loadingSupervisees = true;
      try {
        const r = await fetch(
          `/site/general/supervisee/${this.queries.practitioner}`,
        );
        const data = await r.json();
        if (Array.isArray(data)) {
          this.supervisees = data.map((s) => ({
            id: s.practitioner || s.id,
            name: s.name,
            position: s.designation || "",
            grade: s.grade || "",
          }));
        }
      } catch (e) {
        console.error("Error loading supervisees:", e);
      } finally {
        this.loadingSupervisees = false;
        this.superviseesFetched = true;
      }
    },

    extractName(resource) {
      if (!resource) return "";
      const name = resource.name?.[0];
      if (!name) return "";
      const parts = [...(name.given || []), name.family].filter(Boolean);
      return parts.join(" ");
    },

    initials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .map((p) => p[0])
        .join("")
        .toUpperCase()
        .slice(0, 2);
    },

    buildUrl(route, extraParams = {}) {
      const params = new URLSearchParams({
        path: this.basePath,
        practitioner: this.queries.practitioner,
        ...extraParams,
      });
      return `${route}?${params}`;
    },

    async loadPerfConfig() {
      try {
        const [configRes, overrideRes, fyRes] = await Promise.all([
          fetch("/fhir/Parameters/performance-config").then((r) =>
            r.ok ? r.json() : null,
          ),
          fetch("/fhir/Parameters/performance-override-config").then((r) =>
            r.ok ? r.json() : null,
          ),
          fetch("/site/leave/getFinancialYear").then((r) => r.json()),
        ]);
        if (!configRes) return;
        const currentFY = fyRes?.year || "";
        // shiftFY helper
        const shift = (fy, d) => {
          if (!fy?.includes("/")) return fy;
          const [s, e] = fy.split("/").map(Number);
          return `${s + d}/${e + d}`;
        };
        // Parse overrides
        const overrides = {};
        for (const p of overrideRes?.parameter || []) {
          const get = (n) =>
            (p.part || []).find((pt) => pt.name === n)?.valueString || "";
          overrides[p.name] = {
            fiscalYear: get("fiscal-year"),
            overrideEnd: get("override-end"),
            status: get("status"),
          };
        }
        // Parse each window
        // const today = new Date("2027-04-20");
        const today = new Date();
        const todayStr =
          String(today.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(today.getDate()).padStart(2, "0");
        const fraction = (mmdd) => {
          if (!mmdd) return 0;
          const [mm, dd] = mmdd.split("-").map(Number);
          const days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
          return (
            (days.slice(0, mm - 1).reduce((a, b) => a + b, 0) + dd - 1) / 365
          );
        };
        const inRange = (s, e) => {
          const t = fraction(todayStr),
            sf = fraction(s),
            ef = fraction(e);
          return ef < sf ? t >= sf || t <= ef : t >= sf && t <= ef;
        };
        const cfg = {};
        for (const p of configRes.parameter || []) {
          const get = (n) =>
            (p.part || []).find((pt) => pt.name === n)?.valueString || "";
          const ctx = get("fiscal-year-context");
          const d = ctx === "next" ? 1 : ctx === "previous" ? -1 : 0;
          const derivedTargetFY = ctx ? shift(currentFY, d) : currentFY;
          const baseOpen = inRange(get("start-date"), get("end-date"));
          const ov = overrides[p.name];

          // OVERRIDE FY CHECK — compare against currentFY (stable), not derivedTargetFY
          // (which shifts after April and breaks cross-quarter overrides).
          //
          // ctx="next"     → the "next" year is now currentFY once April passes
          // ctx="current"  → always currentFY
          // ctx="previous" → always one year behind currentFY
          //
          // This ensures each window's override is scoped to its own fiscal year
          // and goal-settings overrides cannot accidentally activate review windows.
          const ovActive =
            ov?.status === "active" && new Date(ov.overrideEnd) >= today;

          // When an override is active, its fiscalYear is the target (admin's intent).
          const targetFY = ovActive ? ov.fiscalYear : derivedTargetFY;
          cfg[p.name] = {
            isOpen: baseOpen || ovActive,
            targetFY,
            context: ctx,
            hasOverride: ovActive,
          };
        }
        this.perfConfig = cfg;
        this.perfConfigLoaded = true;
      } catch (e) {
        console.error("loadPerfConfig error", e);
      }
    },

    goToPlanning() {
      window.location.href = this.buildUrl("/custom/performance-planner");
    },

    goToAnalysis() {
      window.location.href = this.buildUrl("/custom/performance-analysis");
    },

    goToAdjustment() {
      window.location.href = this.buildUrl(
        "/custom/performance-plan-adjustment",
      );
    },

    viewMyReview(reviewerCode) {
      window.location.href = this.buildUrl("/custom/performance-review", {
        reviewer: reviewerCode,
        period: this.activePeriod,
      });
    },

    viewStaffPlan(person) {
      const params = new URLSearchParams({
        path: this.basePath,
        practitioner: person.id,
      });
      window.location.href = `/custom/performance-planner?${params}`;
    },

    viewStaffAnalysis(person) {
      const params = new URLSearchParams({
        path: this.basePath,
        practitioner: person.id,
      });
      window.location.href = `/custom/performance-analysis?${params}`;
    },

    reviewStaff(person, reviewerType) {
      const params = new URLSearchParams({
        path: this.basePath,
        practitioner: person.id,
        reviewer: reviewerType,
        period: this.activePeriod,
      });
      window.location.href = `/custom/performance-review?${params}`;
    },
  },
};
</script>

